// TASK-0038 — V1 Journal-derived Seen/Unseen State, product acceptance in real
// WebView2. No simulated DOM, no alternate renderer, no personal data: both
// trees under test were generated by task0038-seed-proof.py and die with the
// proof root.
//
// Two phases, one REAL process restart between them (run by the .ps1):
//
//   phase 1  first index -> nothing unseen; create -> unseen change, new
//            element; selecting it marks nothing; mark the change -> no longer
//            new; modify -> unseen but not new; mark the element; several
//            changes -> « Tout marquer vu » (first click opens a confirmation,
//            « Annuler » mutates nothing, confirming marks everything); a
//            change AFTER mark-all stays unseen; then a second brain:
//            independent, nothing shared either way.
//   phase 2  after the real restart: the very same states, flag for flag.
//
// Every filesystem change is made by THIS script directly on disk, outside the
// product process, between two real `Actualiser` clicks. Reuses the
// TASK-0033..0037 harness technique (REAL_ROOT registered directly into a
// fresh sandbox catalogue, the real product driven through CDP).
import assert from "node:assert/strict";
import { readFile, writeFile, rm } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0038-[a-f0-9]+$/.test(variant));
assert(phase === 1 || phase === 2);

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, secondBrainId, absolutePath, secondAbsolutePath } = seed;
const proofRoot = join(".filetopo-sandbox", variant);
const root = absolutePath; // real absolute paths, used only by THIS script's own fs calls — never sent into the page.
const secondRoot = secondAbsolutePath;

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ??
        r.exceptionDetails.exception?.value ??
        JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const exposedPayloads = [];
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`,
  );
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
const jargon = [
  "stable_key",
  "stableKey",
  "identity_provenance",
  "identityProvenance",
  "SYS1:",
  "PFv1:",
  "PATH_FALLBACK",
  "fileId",
  "file_id",
  "volumeSerial",
  "volume_serial",
];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal identity jargon "${word}" leaked into ${where}`);
}
function assertNoPathLeak(text, where) {
  for (const path of [root, secondRoot]) {
    const escaped = path.split("\\").join("\\\\");
    assert(!text.includes(path) && !text.includes(escaped), `absolute path leaked into ${where}`);
  }
}
async function assertConfidential() {
  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  assertNoJargon(bodyText, "page body text");
  for (const payload of exposedPayloads) {
    assertNoPathLeak(payload, "an invoke payload");
    assertNoJargon(payload, "an invoke payload");
  }
}

async function waitForAppReady() {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`!!document.querySelector('[data-testid="change-journal"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
}
const revisionExpression = `(() => { const t = document.querySelector('[data-testid="report-brain"]')?.textContent ?? ''; const m = /révision (\\d+)/.exec(t); return m ? Number(m[1]) : -1; })()`;
const currentRevision = () => evaluate(revisionExpression);
/** One real Actualiser click; resolves with the counters the UI shows for it. */
async function refreshAndSummarize() {
  const before = await currentRevision();
  await activate('[data-testid="lifecycle-refresh"]');
  await until(`${revisionExpression} > ${before}`);
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled`);
  await pause(400);
  const raw = await evaluate(
    `document.querySelector('[data-testid="change-summary"]')?.getAttribute('data-summary') ?? 'null'`,
  );
  const summary = JSON.parse(raw);
  assert(summary, "the report must show the change counters after Actualiser");
  return summary;
}
function assertCounters(summary, expected, where) {
  const actual = {
    created: summary.created,
    modified: summary.modified,
    renamed: summary.renamed,
    moved: summary.moved,
    deleted: summary.deleted,
    total: summary.total,
  };
  assert.deepEqual(actual, { created: 0, modified: 0, renamed: 0, moved: 0, deleted: 0, total: 0, ...expected }, where);
}
async function resolve(id, relativePath) {
  const reference = await invoke("map_resolve_node", { brainId: id, relativePath });
  assert(reference, `no node resolves at ${relativePath}`);
  return reference.nodeId;
}

// ---- the real panels ---------------------------------------------------------
async function openJournal() {
  const open = await evaluate(`document.querySelector('[data-testid="journal-toggle"]').getAttribute('aria-expanded') === 'true'`);
  if (!open) await activate('[data-testid="journal-toggle"]');
  await until(`!!document.querySelector('[data-testid="journal-total"]')`);
}
/** What the journal panel shows right now (first page). */
const uiEvents = () =>
  evaluate(`[...document.querySelectorAll('[data-testid="journal-event"]')].map((e) => ({
    eventId: Number(e.getAttribute('data-event-id')),
    nature: e.getAttribute('data-nature'),
    nodeId: Number(e.getAttribute('data-node-id')),
    present: e.getAttribute('data-node-present') === 'true',
    seen: e.getAttribute('data-seen') === 'true',
    badge: e.querySelector('[data-testid="journal-seen-badge"]')?.textContent ?? '',
    hasMark: !!e.querySelector('[data-testid="journal-mark-seen"]'),
    hasSelect: !!e.querySelector('[data-testid="journal-select"]'),
  }))`);
const uiUnseenTotal = () =>
  evaluate(`Number(document.querySelector('[data-testid="journal-unseen-total"]')?.getAttribute('data-unseen-total') ?? -1)`);
const waitUnseen = (n) =>
  until(`Number(document.querySelector('[data-testid="journal-unseen-total"]')?.getAttribute('data-unseen-total') ?? -1) === ${n}`);
const uiMarkAllDisabled = () => evaluate(`document.querySelector('[data-testid="journal-mark-all"]')?.disabled ?? null`);
const uiConfirmOpen = () => evaluate(`!!document.querySelector('[data-testid="journal-mark-all-confirm"]')`);
/** The backend's own page — the reference the UI is compared with. */
async function apiPage(id) {
  const page = await invoke("map_change_journal", { brainId: id, natures: [], after: null, limit: 50 });
  assert.equal(page.brainId, id, "a journal page names the brain it was read from");
  return page;
}
const flagsOf = (page) => page.items.map((e) => [e.eventId, e.seen]);
/** The node badge in the details panel: `new`, `unseen`, `seen`, or null. */
const nodeBadge = () =>
  evaluate(`document.querySelector('[data-testid="node-state-badge"]')?.getAttribute('data-state') ?? null`);
const nodeBadgeText = () => evaluate(`document.querySelector('[data-testid="node-state-badge"]')?.textContent ?? ''`);
async function waitNodeBadge(state) {
  try {
    await until(
      `document.querySelector('[data-testid="node-state-badge"]')?.getAttribute('data-state') === ${JSON.stringify(state)}`,
      30000,
    );
  } catch (error) {
    console.error(
      "DIAGNOSTIC node badge:",
      JSON.stringify({
        expected: state,
        shown: await nodeBadge(),
        text: await nodeBadgeText(),
        error: await evaluate(`document.querySelector('[data-testid="node-state-error"]')?.textContent ?? null`),
        revision: await currentRevision(),
        selectedRows: await evaluate(`document.querySelector('.details__name')?.textContent ?? null`),
      }),
    );
    throw error;
  }
}
/** Selects a node through the journal's own « Afficher » button. */
async function selectViaJournal(nodeId) {
  await openJournal();
  const selector = `[data-testid="journal-event"][data-node-id="${nodeId}"] [data-testid="journal-select"]`;
  await until(`!!document.querySelector(${JSON.stringify(selector)})`);
  await activate(selector);
  await until(`!!document.querySelector('[data-testid="node-state-badge"]')`);
}
async function markChangeInPanel(eventId) {
  await activate(`[data-testid="journal-event"][data-event-id="${eventId}"] [data-testid="journal-mark-seen"]`);
}

const results = {};
await waitForAppReady();

if (phase === 1) {
  // ---- 1 — first index: baseline, nothing unseen ---------------------------
  const first = await refreshAndSummarize();
  assert.equal(first.baselineEstablished, true, "a first build establishes the baseline");
  await openJournal();
  await waitUnseen(0);
  results.firstBuildNothingUnseen = (await uiEvents()).length === 0;
  results.markAllDisabledWhenNothingUnseen = (await uiMarkAllDisabled()) === true;
  assert(results.firstBuildNothingUnseen && results.markAllDisabledWhenNothingUnseen);
  const overview = await invoke("map_open", { brainId });
  results.schemaVersion = overview.schemaVersion;
  assert.equal(overview.schemaVersion, 6, "the product runs on the v6 schema");
  const quiet = await refreshAndSummarize();
  assertCounters(quiet, {}, "no-op refresh counters");
  await waitUnseen(0);

  // ---- 2 — CREATED: an unseen change and a new element ----------------------
  await writeFile(join(root, "nouveau.txt"), "synthetique — objet cree\n", "utf8");
  assertCounters(await refreshAndSummarize(), { created: 1, total: 1 }, "create counters");
  const createdId = await resolve(brainId, "nouveau.txt");
  await waitUnseen(1);
  let events = await uiEvents();
  assert.equal(events.length, 1);
  results.createEventUnseen =
    events[0].nature === "CREATED" && events[0].nodeId === createdId && !events[0].seen && /Non vu/.test(events[0].badge) && events[0].hasMark;
  assert(results.createEventUnseen, "the CREATED change is shown as « Non vu » with a « Marquer vu » button");
  const createdEventId = events[0].eventId;
  let api = await apiPage(brainId);
  assert(api.items[0].seen === false && api.unseenTotal === 1, "the backend agrees: one unseen change");

  // Select the element through the journal: it is « Nouveau », and merely
  // selecting it marks nothing.
  await selectViaJournal(createdId);
  await waitNodeBadge("new");
  assert(/Nouveau/.test(await nodeBadgeText()), "the state is a word, not only a colour");
  const hasElementButton = await evaluate(`!!document.querySelector('[data-testid="node-mark-seen"]')`);
  await pause(1500); // however long it stays selected, nothing is marked
  api = await apiPage(brainId);
  events = await uiEvents();
  results.createNodeNewAndUnseen = hasElementButton && (await nodeBadge()) === "new";
  results.selectionDidNotMarkSeen = api.items[0].seen === false && api.unseenTotal === 1 && !events[0].seen && (await nodeBadge()) === "new";
  assert(results.createNodeNewAndUnseen && results.selectionDidNotMarkSeen, "selecting an element never marks it seen");

  // ---- 3 — mark the CHANGE: the element is no longer new -------------------
  await markChangeInPanel(createdEventId);
  await waitUnseen(0);
  await waitNodeBadge("seen");
  events = await uiEvents();
  results.markChangeNodeNoLongerNew =
    events[0].seen && /Vu/.test(events[0].badge) && !/Non vu/.test(events[0].badge) && !events[0].hasMark && (await nodeBadge()) === "seen";
  assert(results.markChangeNodeNoLongerNew);
  assert.equal((await apiPage(brainId)).items[0].seen, true, "the backend persisted the acknowledgement");

  // ---- 4 — MODIFIED: unseen, but not new ------------------------------------
  await writeFile(join(root, "nouveau.txt"), "synthetique — objet cree, puis modifie, donc plus long\n", "utf8");
  assertCounters(await refreshAndSummarize(), { modified: 1, total: 1 }, "modify counters");
  await waitUnseen(1);
  // An Actualiser puts the selection back on the root (existing product
  // behaviour): the element is selected again through the journal.
  await selectViaJournal(createdId);
  await waitNodeBadge("unseen");
  results.modifyNodeUnseenNotNew = (await nodeBadge()) === "unseen" && /Non vu/.test(await nodeBadgeText());
  assert(results.modifyNodeUnseenNotNew, "a later change makes the element unseen again, but it is not new");

  // ---- 5 — mark the ELEMENT ---------------------------------------------------
  await activate('[data-testid="node-mark-seen"]');
  await waitNodeBadge("seen");
  await waitUnseen(0);
  events = await uiEvents();
  results.markElementSeen = events.every((e) => e.seen) && (await apiPage(brainId)).unseenTotal === 0;
  assert(results.markElementSeen, "marking the element acknowledged its changes, in the journal too");

  // ---- 6 — several changes, then « Tout marquer vu » ----------------------------
  for (const name of ["lot-1.txt", "lot-2.txt", "lot-3.txt"]) {
    await writeFile(join(root, name), `synthetique ${name}\n`, "utf8");
  }
  await writeFile(join(root, "a-modifier.txt"), "synthetique — apres, plus long qu'avant\n", "utf8");
  await rm(join(root, "a-supprimer.txt"));
  const batch = await refreshAndSummarize();
  assertCounters(batch, { created: 3, modified: 1, deleted: 1, total: 5 }, "batch counters");
  await waitUnseen(5);
  results.unseenBeforeMarkAll = await uiUnseenTotal();
  const totalBefore = (await apiPage(brainId)).total;

  // First click: only the confirmation opens.
  await activate('[data-testid="journal-mark-all"]');
  await until(`!!document.querySelector('[data-testid="journal-mark-all-confirm"]')`);
  api = await apiPage(brainId);
  results.firstClickNoMutation = (await uiConfirmOpen()) && api.unseenTotal === 5 && (await uiUnseenTotal()) === 5;
  assert(results.firstClickNoMutation, "the first click opens the confirmation and mutates nothing");
  // « Annuler »: still nothing.
  await activate('[data-testid="journal-mark-all-cancel"]');
  await until(`!document.querySelector('[data-testid="journal-mark-all-confirm"]')`);
  api = await apiPage(brainId);
  results.cancelNoMutation = !(await uiConfirmOpen()) && api.unseenTotal === 5 && (await uiUnseenTotal()) === 5;
  assert(results.cancelNoMutation, "« Annuler » mutates nothing");
  // Second gesture, explicit confirmation.
  await activate('[data-testid="journal-mark-all"]');
  await until(`!!document.querySelector('[data-testid="journal-mark-all-confirm"]')`);
  await activate('[data-testid="journal-mark-all-confirm-yes"]');
  await waitUnseen(0);
  events = await uiEvents();
  api = await apiPage(brainId);
  results.confirmMarksEverything =
    events.length > 0 && events.every((e) => e.seen && /Vu/.test(e.badge)) && api.unseenTotal === 0 && api.total === totalBefore && (await uiMarkAllDisabled()) === true;
  assert(results.confirmMarksEverything, "after confirmation every change is seen, none was removed");
  const deleted = events.find((e) => e.nature === "DELETED");
  results.deletedAcknowledged = !!deleted && deleted.seen && !deleted.present && !deleted.hasSelect;
  assert(results.deletedAcknowledged, "a DELETED change is acknowledged as a change and stays history only");

  // ---- 7 — a change AFTER mark-all stays unseen ---------------------------------
  await writeFile(join(root, "apres.txt"), "synthetique — apres le tout marquer vu\n", "utf8");
  assertCounters(await refreshAndSummarize(), { created: 1, total: 1 }, "post mark-all counters");
  await waitUnseen(1);
  events = await uiEvents();
  const apresId = await resolve(brainId, "apres.txt");
  const newest = events[0];
  results.changeAfterMarkAllUnseen =
    newest.nature === "CREATED" && newest.nodeId === apresId && !newest.seen && events.slice(1).every((e) => e.seen);
  assert(results.changeAfterMarkAllUnseen, "only the change detected after mark-all is unseen");
  await selectViaJournal(apresId);
  await waitNodeBadge("new");
  results.nodeAfterMarkAllNew = (await nodeBadge()) === "new";
  assert(results.nodeAfterMarkAllNew);

  // What phase 2 must find again.
  const firstBrainPage = await apiPage(brainId);
  results.firstBrainSnapshot = {
    flags: flagsOf(firstBrainPage),
    unseenTotal: firstBrainPage.unseenTotal,
    total: firstBrainPage.total,
    apresId,
    acknowledgedNodeId: createdId,
  };

  // ---- 8 — a second brain: nothing shared ----------------------------------------
  await activate('[data-testid="composition-add-trigger"]');
  await until(`!!document.querySelector('[data-testid="composition-add-item-${secondBrainId}"]')`);
  await activate(`[data-testid="composition-add-item-${secondBrainId}"]`);
  await until(`!!document.querySelector('[data-testid="composition-chip-${secondBrainId}"]')`);
  await activate(`[data-testid="composition-chip-${secondBrainId}"]`);
  await until(`document.querySelector('[data-testid="composition-chip-${secondBrainId}"]')?.getAttribute('aria-current') === 'true'`);
  const secondFirst = await refreshAndSummarize();
  results.secondBrainBaseline = secondFirst.baselineEstablished === true;
  assert(results.secondBrainBaseline, "the second brain establishes its own baseline");
  await openJournal();
  await waitUnseen(0);
  assert.equal((await uiEvents()).length, 0, "the second brain shows none of the first brain's history");

  await writeFile(join(secondRoot, "b-nouveau-1.txt"), "synthetique b1\n", "utf8");
  await writeFile(join(secondRoot, "b-nouveau-2.txt"), "synthetique b2\n", "utf8");
  assertCounters(await refreshAndSummarize(), { created: 2, total: 2 }, "second brain counters");
  await waitUnseen(2);
  const secondEvents = await uiEvents();
  results.secondBrainUnseen = secondEvents.length === 2 && secondEvents.every((e) => !e.seen && /Non vu/.test(e.badge));
  assert(results.secondBrainUnseen, "the second brain's own changes are unseen, whatever the first brain acknowledged");
  // Refreshing the second brain (both are composed) must not have touched the first.
  let firstNow = await apiPage(brainId);
  results.firstBrainUntouchedBySecond =
    JSON.stringify(flagsOf(firstNow)) === JSON.stringify(results.firstBrainSnapshot.flags) && firstNow.unseenTotal === 1;
  assert(results.firstBrainUntouchedBySecond);

  // Mark one change of the second brain through its panel: the first is unmoved.
  await markChangeInPanel(secondEvents[0].eventId);
  await waitUnseen(1);
  let secondNow = await apiPage(secondBrainId);
  assert(secondNow.unseenTotal === 1 && secondNow.items.filter((e) => e.seen).length === 1);
  // …and mark-all on the second brain through the API leaves the first alone.
  const markedAll = await invoke("map_change_mark_all_seen", { brainId: secondBrainId });
  assert.equal(markedAll.brainId, secondBrainId, "the answer names the brain it acted on");
  secondNow = await apiPage(secondBrainId);
  firstNow = await apiPage(brainId);
  results.markingSecondLeavesFirstAlone =
    secondNow.unseenTotal === 0 && firstNow.unseenTotal === 1 && JSON.stringify(flagsOf(firstNow)) === JSON.stringify(results.firstBrainSnapshot.flags);
  assert(results.markingSecondLeavesFirstAlone);
  results.secondBrainSnapshot = { flags: flagsOf(secondNow), unseenTotal: secondNow.unseenTotal, total: secondNow.total };

  // Switch back to the first brain: the panel shows ITS state, not the second's.
  await activate(`[data-testid="composition-chip-${brainId}"]`);
  await until(`document.querySelector('[data-testid="composition-chip-${brainId}"]')?.getAttribute('aria-current') === 'true'`);
  await openJournal();
  await waitUnseen(1);
  events = await uiEvents();
  results.switchBackShowsFirstOnly =
    JSON.stringify(events.map((e) => [e.eventId, e.seen])) === JSON.stringify(results.firstBrainSnapshot.flags) &&
    (await uiUnseenTotal()) === 1;
  assert(results.switchBackShowsFirstOnly, "switching back shows the first brain's own flags");

  await assertConfidential();
  results.noAbsolutePathOrIdentityLeak = true;
} else {
  // ---- phase 2: after a REAL process restart ---------------------------------
  const before = JSON.parse(await readFile(join(proofRoot, "phase1.json"), "utf8"));
  const first = before.firstBrainSnapshot;
  const second = before.secondBrainSnapshot;
  await until(`${revisionExpression} >= 0`);
  await openJournal();

  // Backend truth, both brains, flag for flag.
  const firstPage = await apiPage(brainId);
  results.firstBrainFlagsIdentical =
    JSON.stringify(flagsOf(firstPage)) === JSON.stringify(first.flags) && firstPage.total === first.total;
  results.firstBrainUnseenTotal = firstPage.unseenTotal;
  assert(results.firstBrainFlagsIdentical, "the first brain's acknowledgements survive the restart, flag for flag");
  assert.equal(firstPage.unseenTotal, first.unseenTotal);
  const secondPage = await apiPage(secondBrainId);
  results.secondBrainFlagsIdentical =
    JSON.stringify(flagsOf(secondPage)) === JSON.stringify(second.flags) && secondPage.total === second.total;
  results.secondBrainUnseenTotal = secondPage.unseenTotal;
  assert(results.secondBrainFlagsIdentical, "the second brain's acknowledgements survive the restart, flag for flag");
  assert.equal(secondPage.unseenTotal, second.unseenTotal);

  // Element states persisted too.
  const stillNew = await invoke("map_node_change_state", { reference: { brainId, nodeId: first.apresId } });
  results.newNodeStillNew = stillNew.isNew === true && stillNew.isUnseen === true && stillNew.brainId === brainId;
  const acknowledged = await invoke("map_node_change_state", { reference: { brainId, nodeId: first.acknowledgedNodeId } });
  results.acknowledgedNodeStillSeen = acknowledged.isNew === false && acknowledged.isUnseen === false;
  assert(results.newNodeStillNew && results.acknowledgedNodeStillSeen);

  // …and the real panels show that persisted state.
  await waitUnseen(first.unseenTotal);
  const events = await uiEvents();
  await selectViaJournal(first.apresId);
  await waitNodeBadge("new");
  results.panelShowsPersistedState =
    JSON.stringify(events.map((e) => [e.eventId, e.seen])) === JSON.stringify(first.flags) && (await nodeBadge()) === "new";
  assert(results.panelShowsPersistedState, "the panels read the persisted state");

  // A restart must not have re-scanned anything: opening is not a refresh.
  const overview = await invoke("map_open", { brainId });
  results.openAfterRestartReadNoSource = overview.sourceRead === false;
  results.schemaVersion = overview.schemaVersion;
  assert(results.openAfterRestartReadNoSource && overview.schemaVersion === 6);

  await assertConfidential();
  results.noAbsolutePathOrIdentityLeak = true;
}

await writeFile(join(proofRoot, `phase${phase}.json`), JSON.stringify(results));
console.log(JSON.stringify({ ok: true, phase }));

assert.equal(fatal.length, 0, `fatal page/console errors`);
await writeFile(join(proofRoot, `phase${phase}-fatal-count.json`), JSON.stringify(fatal.length));
ws.close();
